/bin/bash -lc "python3 - <<'PY'
import ast,copy,hashlib,json,pathlib,subprocess
proposal=json.loads(pathlib.Path('proposal.json').read_text())
runtime=json.loads(subprocess.check_output(['python3','/workspace/tools.py','resolve','run://r-001'],text=True))
schema=runtime['study_schema']
def validate(value,schema,path='"'$'"'):
 kind=schema.get('type')
 if kind=='object':
  assert isinstance(value,dict),(path,'object')
  assert set(schema.get('required',[]))<=value.keys(),(path,'required')
  if schema.get('additionalProperties') is False: assert set(value)<=schema.get('properties',{}).keys(),(path,'extra properties')
  for k,v in value.items():
   if k in schema.get('properties',{}): validate(v,schema['properties'][k],path+'.'+k)
 elif kind=='array':
  assert isinstance(value,list),(path,'array')
  assert len(value)>=schema.get('minItems',0),(path,'minItems')
  for i,item in enumerate(value): validate(item,schema.get('items',{}),path+'['+str(i)+']')
 elif kind=='string':
  assert isinstance(value,str) and len(value)>=schema.get('minLength',0),(path,'string')
 if 'enum' in schema: assert value in schema['enum'],(path,'enum')
 if 'const' in schema: assert value==schema['const'],(path,'const')
validate(proposal['study'],schema)
assert proposal['study']['protocol_ref']==runtime['required_study_protocol_ref']
allowed=set(runtime['context']['allowed_observation_ids'])
assert proposal['parent_trial'] in allowed
assert all(r in allowed for r in proposal['study']['evidence_refs'])
assert 1<=len(proposal['variants'])<=4
assert len({v['name'] for v in proposal['variants']})==len(proposal['variants'])
assert len({v['file'] for v in proposal['variants']})==len(proposal['variants'])
assert any(v['role']=='candidate' for v in proposal['variants'])
base=ast.parse(pathlib.Path('candidate.py').read_text())
def normalize(tree):
 t=copy.deepcopy(tree)
 for n in t.body:
  if isinstance(n,ast.Assign) and any(isinstance(a,ast.Name) and a.id=='CONFIG' for a in n.targets): n.value=ast.Constant(value='CONFIG_NORMALIZED')
 return ast.dump(t,include_attributes=False)
base_hash=hashlib.sha256(pathlib.Path('candidate.py').read_bytes()).hexdigest()
incumbent=next(t for t in runtime['context']['history'] if t['id']==proposal['parent_trial'])
assert base_hash==incumbent['source_sha256']
assert hashlib.sha256(pathlib.Path('baseline_reference.py').read_bytes()).hexdigest()=='ee10868f589c077b19f57a1fb07702c947c56e970994cdc537ef83ea2b8bc943'
canonical=None
for v in proposal['variants']:
 file=v['file']; assert pathlib.Path(file).name==file and file.endswith('.py')
 tree=ast.parse(pathlib.Path(file).read_text()); compile(tree,file,'exec')
 assert normalize(ast.Module(body=tree.body[:len(base.body)],type_ignores=[]))==normalize(base),(file,'inherited prefix changed')
 assert normalize(tree)==(canonical or normalize(tree)),(file,'nonconfig difference')
 canonical=normalize(tree)
 config=ast.literal_eval(next(n.value for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(a,ast.Name) and a.id=='CONFIG' for a in n.targets)))
 assert config==v['config']
 for n in ast.walk(tree):
  if isinstance(n,ast.Import): assert all(a.name in {'math','torch','numpy','typing','copy','functools','collections','itertools','dataclasses','contextlib'} for a in n.names)
  if isinstance(n,ast.ImportFrom): assert n.module in {'torch','numpy','math','typing','copy','functools','collections','itertools','dataclasses','contextlib'}
  if isinstance(n,ast.Call) and isinstance(n.func,ast.Name): assert n.func.id not in {'open','eval','exec','compile','__import__','print','input'}
  if isinstance(n,ast.Attribute): assert n.attr not in {'load','save','load_state_dict','manual_seed','seed','backward','step','read_text','write_text'}
 print(file,'syntax/source/config PASS','SHA256',hashlib.sha256(pathlib.Path(file).read_bytes()).hexdigest())
new_class=ast.parse(pathlib.Path(proposal['variants'][0]['file']).read_text()).body[-1]
diag=next(n for n in new_class.body if isinstance(n,ast.FunctionDef) and n.name=='diagnostics')
initial=next(n for n in diag.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='result' for t in n.targets))
# Explicit34 globals + (2 mass identities +2 replacements)*2 +4 field scalars*2.
count=len(initial.value.keys)+2*(2+2)+2*4
assert count<=64
print('Diagnostic scalar count',count,'<=64; no prohibited IO, training hooks or extra RNG.')
print('Prospective study schema, evidence IDs, parent SHA, four-cell AST/config consistency: PASS.')
print('Expected extra parameters 24*128=3072; expected total',incumbent['parameters']+3072,'dense',incumbent['dense_parameters']+3072)
print('Torch absent: no runtime, gradient, inference or actual parameter count claim.')
PY"

